<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarCuentasCentro, cambiarEstadoCentroCostos, guardarCentroCostos, listarCentrosCostos } from '../services/centrosCostos'
import type { CentroCostos, CentroCostosPayload, CentroOption, CuentaCentro } from '../interfaces/centroCostos.interface'
const rows=ref<CentroCostos[]>([]),procesos=ref<CentroOption[]>([]),subprocesos=ref<CentroOption[]>([]),actividades=ref<CentroOption[]>([]),sucursales=ref<CentroOption[]>([]),clasificadores=ref<CentroOption[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const blank=():CentroCostosPayload=>({codigo:'',nombre:'',tipo:'D',cuenta_contable_9_id:0,cuenta_contable_7_id:0,sucursales_id:null,proceso_id:null,sub_proceso_id:null,actividad_id:null,clasificador_gastos_id:null})
const form=reactive<CentroCostosPayload>(blank()),cuentaTextos=ref<Record<'9'|'7',string>>({9:'',7:''}),accountModal=ref(false),accountTarget=ref<'9'|'7'>('9'),accountQuery=ref(''),accounts=ref<CuentaCentro[]>([])
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarCentrosCostos(criterio.value,next);rows.value=r.data;procesos.value=r.procesos??[];subprocesos.value=r.subprocesos??[];actividades.value=r.actividades??[];sucursales.value=r.sucursales??[];clasificadores.value=r.clasificadores??[];page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:CentroCostos){editing.value=item?.id??null;Object.assign(form,item??blank());cuentaTextos.value={9:item?.cuenta_contable_9?`${item.cuenta_contable_9.cta_contable} - ${item.cuenta_contable_9.descripcion}`:'',7:item?.cuenta_contable_7?`${item.cuenta_contable_7.cta_contable} - ${item.cuenta_contable_7.descripcion}`:''};error.value='';modal.value=true}
function openAccount(target:'9'|'7'){accountTarget.value=target;accountQuery.value='';accounts.value=[];accountModal.value=true}
async function searchAccounts(){if(accountQuery.value.trim().length<2)return void(error.value='Ingrese al menos 2 caracteres para buscar la cuenta.');try{accounts.value=await buscarCuentasCentro(accountQuery.value.trim())}catch(v){error.value=message(v)}}
function chooseAccount(account:CuentaCentro){if(accountTarget.value==='9')form.cuenta_contable_9_id=account.id;else form.cuenta_contable_7_id=account.id;cuentaTextos.value[accountTarget.value]=`${account.cta_contable} - ${account.descripcion}`;accountModal.value=false}
async function save(){const codigo=form.codigo.trim(),nombre=form.nombre.trim();if(!codigo||codigo.length>20)return void(error.value='Ingrese un código de hasta 20 caracteres.');if(!nombre||nombre.length>191)return void(error.value='Ingrese un nombre de hasta 191 caracteres.');if(!form.cuenta_contable_9_id||!form.cuenta_contable_7_id)return void(error.value='Seleccione las cuentas contables N.° 9 y N.° 7.');saving.value=true;error.value='';try{await guardarCentroCostos(editing.value,{...form,codigo:codigo.toUpperCase(),nombre:nombre.toUpperCase()});modal.value=false;success.value=`Centro de costos ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:CentroCostos){if(!confirm(`¿Desea ${item.activo?'desactivar':'activar'} el centro ${item.codigo}?`))return;try{await cambiarEstadoCentroCostos(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
const tipo=(value:string)=>value==='D'?'Directo':value==='I'?'Indirecto':'Receptor'
onMounted(()=>load())
</script>
<template><div class="page" style="--a:#655b9c"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/parametros-costos">Parámetros de costos</RouterLink> / Centros de costos</nav><header class="hero"><div class="mark">CC</div><div><small>MIA · CONTABILIDAD · COSTOS</small><h1>Centros de costos</h1><p>Configura centros, cuentas contables y su estructura operativa asociada.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo centro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="criterio" placeholder="Buscar por código o nombre"><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando centros…</div><div v-else-if="!rows.length" class="empty">No se encontraron centros de costos.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Código</th><th>Nombre</th><th>Sucursal</th><th>Proceso</th><th>Tipo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td>{{item.sucursal?.nombre||'—'}}</td><td>{{item.proceso?.nombre||'—'}}</td><td>{{tipo(item.tipo)}}</td><td><span :class="item.activo?'ok':'bad'">{{item.activo?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">Estado</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog wide" @submit.prevent="save"><header><div><small>PARÁMETROS DE COSTOS</small><h2>{{editing?'Editar':'Nuevo'}} centro de costos</h2></div><button type="button" @click="modal=false">×</button></header><div class="form-grid"><label>Código *<input v-model="form.codigo" required maxlength="20" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Nombre *<input v-model="form.nombre" required maxlength="191" @input="form.nombre=form.nombre.toUpperCase()"></label><label>Tipo *<select v-model="form.tipo"><option value="D">Directo</option><option value="I">Indirecto</option><option value="R">Receptor</option></select></label><label>Cuenta contable N.° 9 *<span class="account"><input :value="cuentaTextos['9']||'Sin seleccionar'" readonly><button type="button" @click="openAccount('9')">Buscar</button></span></label><label>Cuenta contable N.° 7 *<span class="account"><input :value="cuentaTextos['7']||'Sin seleccionar'" readonly><button type="button" @click="openAccount('7')">Buscar</button></span></label><label>Sucursal<select v-model="form.sucursales_id"><option :value="null">Opcional</option><option v-for="o in sucursales" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Proceso<select v-model="form.proceso_id"><option :value="null">Opcional</option><option v-for="o in procesos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Subproceso<select v-model="form.sub_proceso_id"><option :value="null">Opcional</option><option v-for="o in subprocesos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Actividad<select v-model="form.actividad_id"><option :value="null">Opcional</option><option v-for="o in actividades" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Clasificador de gastos<select v-model="form.clasificador_gastos_id"><option :value="null">Opcional</option><option v-for="o in clasificadores" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div><div v-if="accountModal" class="backdrop top" @mousedown.self="accountModal=false"><section class="dialog"><header><h2>Buscar cuenta contable</h2><button @click="accountModal=false">×</button></header><form class="account-search" @submit.prevent="searchAccounts"><input v-model="accountQuery" placeholder="Código o descripción"><button>Buscar</button></form><div class="results"><button v-for="a in accounts" :key="a.id" @click="chooseAccount(a)"><b>{{a.cta_contable}}</b><span>{{a.descripcion}}</span></button></div></section></div></div></template>
<style scoped src="./costCrud.css"></style><style scoped>.wide{width:min(900px,100%)}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.account{display:flex}.account button{margin-left:5px}.top{z-index:110}.account-search{display:flex;gap:6px}.account-search input{flex:1}.results{display:grid;max-height:280px;overflow:auto}.results button{margin-top:5px;display:grid;grid-template-columns:120px 1fr;text-align:left}.results span{margin-left:8px}@media(max-width:760px){.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:480px){.form-grid{grid-template-columns:1fr}}</style>
